class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def all_words_with_prefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]

        def dfs(node, current_word):
            words = []
            if node.is_end:
                words.append(current_word)
            for char, child in node.children.items():
                words.extend(dfs(child, current_word + char))
            return words

        return dfs(node, prefix)

trie = Trie()
words = ["apple", "app", "application", "apply", "banana", "band"]
for word in words:
    trie.insert(word)

print(f"    Inserted words: {words}")
print(f"    Search 'app': {trie.search('app')}")
print(f"    Search 'appl': {trie.search('appl')}")
print(f"    Words starting with 'app': {trie.all_words_with_prefix('app')}")

