def safe_deque_operation(operation, item=None):
    with lock:
        if operation == "append":
            thread_safe_deque.append(item)
        elif operation == "popleft":
            if thread_safe_deque:
                return thread_safe_deque.popleft()
        elif operation == "size":
            return len(thread_safe_deque)

# Demonstrate thread safety
def worker(worker_id):
    for i in range(5):
        safe_deque_operation("append", f"worker_{worker_id}_item_{i}")

threads = []
for i in range(3):
    t = threading.Thread(target=worker, args=(i,))
    threads.append(t)
    t.start()

for t in threads:
    t.join()

print(f"    Items added by threads: {safe_deque_operation('size')}")
items = []
while safe_deque_operation("size") > 0:
    items.append(safe_deque_operation("popleft"))
